func buildRecurringExpenseMatchThenLoader[Q orm.Loadable]() recurringExpenseMatchThenLoader[Q] {
	type PurchaseLoadInterface interface {
		LoadPurchase(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type RecurringExpenseLoadInterface interface {
		LoadRecurringExpense(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type MatchedByMemberLoadInterface interface {
		LoadMatchedByMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return recurringExpenseMatchThenLoader[Q]{
		Purchase: thenLoadBuilder[Q](
			"Purchase",
			func(ctx context.Context, exec bob.Executor, retrieved PurchaseLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadPurchase(ctx, exec, mods...)
			},
		),
		RecurringExpense: thenLoadBuilder[Q](
			"RecurringExpense",
			func(ctx context.Context, exec bob.Executor, retrieved RecurringExpenseLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadRecurringExpense(ctx, exec, mods...)
			},
		),
		MatchedByMember: thenLoadBuilder[Q](
			"MatchedByMember",
			func(ctx context.Context, exec bob.Executor, retrieved MatchedByMemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadMatchedByMember(ctx, exec, mods...)
			},
		),
	}
}

// LoadPurchase loads the recurringExpenseMatch's Purchase into the .R struct
func (o *RecurringExpenseMatch) LoadPurchase(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.Purchase = nil
	o.R.Loaded.Purchase = false

	related, err := o.Purchase(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.RecurringExpenseMatch = o
	related.R.Loaded.RecurringExpenseMatch = true

	o.R.Purchase = related
	o.R.Loaded.Purchase = true
	return nil
}

// LoadPurchase loads the recurringExpenseMatch's Purchase into the .R struct
func (os RecurringExpenseMatchSlice) LoadPurchase(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	purchases, err := os.Purchase(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.Purchase = nil
		o.R.Loaded.Purchase = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range purchases {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.PurchaseID == rel.ID) {
				continue
			}

			rel.R.RecurringExpenseMatch = o
			rel.R.Loaded.RecurringExpenseMatch = true

			o.R.Purchase = rel
			break
		}
	}

	return nil
}

// LoadRecurringExpense loads the recurringExpenseMatch's RecurringExpense into the .R struct
func (o *RecurringExpenseMatch) LoadRecurringExpense(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.RecurringExpense = nil
	o.R.Loaded.RecurringExpense = false

	related, err := o.RecurringExpense(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.RecurringExpenseMatches = RecurringExpenseMatchSlice{o}

	o.R.RecurringExpense = related
	o.R.Loaded.RecurringExpense = true
	return nil
}

// LoadRecurringExpense loads the recurringExpenseMatch's RecurringExpense into the .R struct
func (os RecurringExpenseMatchSlice) LoadRecurringExpense(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	recurringExpenses, err := os.RecurringExpense(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.RecurringExpense = nil
		o.R.Loaded.RecurringExpense = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range recurringExpenses {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.RecurringExpenseID == rel.ID) {
				continue
			}

			rel.R.RecurringExpenseMatches = append(rel.R.RecurringExpenseMatches, o)

			o.R.RecurringExpense = rel
			break
		}
	}

	return nil
}

// LoadMatchedByMember loads the recurringExpenseMatch's MatchedByMember into the .R struct
func (o *RecurringExpenseMatch) LoadMatchedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.MatchedByMember = nil
	o.R.Loaded.MatchedByMember = false

	related, err := o.MatchedByMember(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.MatchedByRecurringExpenseMatches = RecurringExpenseMatchSlice{o}

	o.R.MatchedByMember = related
	o.R.Loaded.MatchedByMember = true
	return nil
}

// LoadMatchedByMember loads the recurringExpenseMatch's MatchedByMember into the .R struct
func (os RecurringExpenseMatchSlice) LoadMatchedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.MatchedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.MatchedByMember = nil
		o.R.Loaded.MatchedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	recurringExpenseMatchByKey := make(map[uuid.UUID][]*RecurringExpenseMatch, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		recurringExpenseMatchByKey[o.MatchedBy] = append(recurringExpenseMatchByKey[o.MatchedBy], o)
	}

	for _, rel := range members {

		owners, ok := recurringExpenseMatchByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.MatchedByMember != nil {
				continue
			}

			rel.R.MatchedByRecurringExpenseMatches = append(rel.R.MatchedByRecurringExpenseMatches, o)

			o.R.MatchedByMember = rel

		}
	}

	return nil
}

type recurringExpenseMatchJoins[Q dialect.Joinable] struct {
	typ              string
	Purchase         modAs[Q, purchaseColumns]
	RecurringExpense modAs[Q, recurringExpenseColumns]
	MatchedByMember  modAs[Q, memberColumns]
}

func (j recurringExpenseMatchJoins[Q]) aliasedAs(alias string) recurringExpenseMatchJoins[Q] {
	return buildRecurringExpenseMatchJoins[Q](buildRecurringExpenseMatchColumns(alias), j.typ)
}

func buildRecurringExpenseMatchJoins[Q dialect.Joinable](cols recurringExpenseMatchColumns, typ string) recurringExpenseMatchJoins[Q] {
	return recurringExpenseMatchJoins[Q]{
		typ: typ,
		Purchase: modAs[Q, purchaseColumns]{
			c: Purchases.Columns,
			f: func(to purchaseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Purchases.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.PurchaseID),
					))
				}

				return mods
			},
		},
		RecurringExpense: modAs[Q, recurringExpenseColumns]{
			c: RecurringExpenses.Columns,
			f: func(to recurringExpenseColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, RecurringExpenses.NameExpr().As(to.Alias())).On(
						to.HouseholdID.EQ(cols.HouseholdID), to.ID.EQ(cols.RecurringExpenseID),
					))
				}

				return mods
			},
		},
		MatchedByMember: modAs[Q, memberColumns]{
			c: Members.Columns,
			f: func(to memberColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Members.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.MatchedBy),
					))
				}

				return mods
			},
		},
	}
}
